changeSet.sql:
CREATE TABLE outbox_events
(
    id                 BIGINT AUTO_INCREMENT PRIMARY KEY NOT NULL,
    aggregate_id       BINARY(16) NOT NULL,
    aggregate_type     VARCHAR(255) NOT NULL,
    event_type         VARCHAR(255) NOT NULL,
    payload            JSON         NOT NULL,
    published          BOOLEAN      NOT NULL DEFAULT false,
    published_at       TIMESTAMP,
    version            INT          NOT NULL DEFAULT 1,
    created_by         VARCHAR(255) NOT NULL DEFAULT 'SYSTEM',
    last_modified_by   VARCHAR(255) NOT NULL DEFAULT 'SYSTEM',
    created_date       TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_modified_date TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);

-- Outbox events indexes
CREATE INDEX idx_outbox_events_published ON outbox_events (published);
CREATE INDEX idx_outbox_events_created_date ON outbox_events (created_date);
CREATE INDEX idx_outbox_events_aggregate_id ON outbox_events (aggregate_id);
CREATE INDEX idx_outbox_events_event_type ON outbox_events (event_type);
CREATE INDEX idx_outbox_events_published_created ON outbox_events (published, created_date);
